// Distributor / dealer application form, complaints and feedback form, and two new dashboard tabs.
// - The Distributor page becomes a 6-step form (business, shop location, 4 photos, registration, next of kin, review).
//   Only details are collected; terms are agreed when a contract is signed.
// - New page  #/feedback  (complaints, feedback, compliments) with a reference number for each.
// - Dashboard: Applications tab (photos, status, notes) and Feedback tab (status, what we did). Both send alerts.
// Needs 03-peacock-forms.sql to have been run in Supabase first.
// Run from the project root AFTER add-dashboard-alerts.mjs:  node add-forms.mjs
// NEW: src/lib/forms.js, src/pages/FeedbackPage.jsx, src/dashboard/ApplicationsAdmin.jsx, src/dashboard/FeedbackAdmin.jsx
// REPLACES: src/pages/DistributorPage.jsx, src/dashboard/DashboardPage.jsx. Git keeps the old ones.
// EDITS: src/pages/PageSwitch.jsx (the #/feedback page), src/pages/ContactPage.jsx (a link to the feedback page, skipped if its text has changed)
// Undo: git checkout . ; git clean -fd src
import fs from "node:fs";
import { createRequire } from "node:module";

const NEW_FILES = {
  "src/lib/forms.js": "import { supabase } from \"./supabase.js\";\nimport { compressImage } from \"../dashboard/uploads.js\";\n\nconst CHARS = \"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\";\nconst code = () => Array.from({ length: 4 }, () => CHARS[Math.floor(Math.random() * CHARS.length)]).join(\"\");\nexport const newReference = prefix => prefix + \"-\" + code();\nconst cut = (v, n) => { const s = String(v == null ? \"\" : v).trim().slice(0, n); return s || null; };\n\n// Saves a distributor / dealer application: first the 4 shop photos (private storage), then the details.\n// Returns { ok: true, reference } or { ok: false, error } with a message the visitor can read.\nexport async function submitApplication(v, photos) {\n  if (!supabase) return { ok: false, error: \"The form is not connected yet. Please contact us on WhatsApp instead.\" };\n  let compressed;\n  try { compressed = await Promise.all(photos.map(f => compressImage(f, 1600, 0.8))); }\n  catch (e) { return { ok: false, error: e.message || \"One of the photos could not be processed. Please use JPG, PNG or WebP photos.\" }; }\n\n  for (let attempt = 0; attempt < 3; attempt++) {\n    const reference = newReference(\"PP-DIST\");\n    const paths = [];\n    for (let i = 0; i < compressed.length; i++) {\n      const path = reference + \"/\" + (i + 1) + \".jpg\";\n      const { error } = await supabase.storage.from(\"applications\").upload(path, compressed[i], { contentType: \"image/jpeg\", upsert: false });\n      if (error) return { ok: false, error: \"A photo could not be uploaded (\" + error.message + \"). Check your connection and try again.\" };\n      paths.push(path);\n    }\n    const { error } = await supabase.from(\"dealer_applications\").insert({\n      reference, kind: v.kind === \"Dealer\" ? \"Dealer\" : \"Distributor\",\n      business_name: cut(v.business, 160), contact_person: cut(v.person, 120), phone: cut(v.phone, 40), email: cut(v.email, 254),\n      shop_town: cut(v.town, 120), shop_address: cut(v.address, 300),\n      years_in_business: Math.max(0, Math.min(100, parseInt(v.years, 10) || 0)),\n      registration_status: v.regStatus, registration_number: cut(v.regNumber, 60),\n      tax_status: v.taxStatus, tin_number: cut(v.tin, 40),\n      kin_name: cut(v.kinName, 120), kin_phone: cut(v.kinPhone, 40), kin_relationship: cut(v.kinRelation, 60),\n      photos: paths, consent: true,\n    });\n    if (!error) return { ok: true, reference };\n    if (error.code !== \"23505\") return { ok: false, error: \"Your application could not be saved (\" + error.message + \"). Please try again, or contact us on WhatsApp.\" };\n  }\n  return { ok: false, error: \"Please try again in a moment.\" };\n}\n\n// Saves a complaint, feedback or compliment.\nexport async function submitFeedback(v) {\n  if (!supabase) return { ok: false, error: \"The form is not connected yet. Please contact us on WhatsApp instead.\" };\n  for (let attempt = 0; attempt < 3; attempt++) {\n    const reference = newReference(\"PP-FB\");\n    const { error } = await supabase.from(\"feedback\").insert({\n      reference, type: v.type, name: cut(v.name, 120), phone: cut(v.phone, 40), email: cut(v.email, 254),\n      product: cut(v.product, 160), place: cut(v.place, 160), message: cut(v.message, 4000), rating: v.rating ? Number(v.rating) : null,\n    });\n    if (!error) return { ok: true, reference };\n    if (error.code !== \"23505\") return { ok: false, error: \"Your message could not be saved (\" + error.message + \"). Please try again, or contact us on WhatsApp.\" };\n  }\n  return { ok: false, error: \"Please try again in a moment.\" };\n}\n",
  "src/pages/FeedbackPage.jsx": "import { useState } from \"react\";\nimport { CONTACT } from \"../config/contact.js\";\nimport { B } from \"../data/theme.js\";\nimport { whatsappReady, whatsappUrl } from \"../utils/messaging.js\";\nimport { submitFeedback } from \"../lib/forms.js\";\nimport PageHero from \"../components/common/PageHero.jsx\";\n\nconst TYPES = [[\"complaint\", \"Complaint\"], [\"feedback\", \"Feedback\"], [\"compliment\", \"Compliment\"]];\nconst EMPTY = { type: \"complaint\", name: \"\", phone: \"\", email: \"\", product: \"\", place: \"\", message: \"\", rating: 0, website: \"\" };\nconst label = { fontSize: 12, fontWeight: 600, color: \"#555\", display: \"block\", marginBottom: 6 };\n\nexport default function FeedbackPage() {\n  const [form, setForm] = useState(EMPTY);\n  const [errors, setErrors] = useState([]);\n  const [busy, setBusy] = useState(false);\n  const [done, setDone] = useState(null);\n  const set = key => e => setForm(f => ({ ...f, [key]: e.target.value }));\n  const ready = whatsappReady(CONTACT.whatsappNumber);\n\n  async function submit() {\n    const e = [];\n    if (!form.name.trim()) e.push(\"Enter your name.\");\n    if (!form.phone.trim() && !form.email.trim()) e.push(\"Enter a phone number or an email so we can reply.\");\n    if (form.message.trim().length < 5) e.push(\"Please tell us a little more in the message box.\");\n    setErrors(e);\n    if (e.length || busy) return;\n    if (form.website) { setDone({ reference: \"PP-FB-0000\" }); return; }\n    setBusy(true);\n    const r = await submitFeedback(form);\n    setBusy(false);\n    if (r.ok) setDone({ reference: r.reference }); else setErrors([r.error]);\n  }\n\n  const card = { background: \"#fff\", border: \"1px solid #eee\", borderRadius: 14, padding: 28 };\n  const pill = active => ({ padding: \"8px 20px\", borderRadius: 22, fontSize: 14, fontWeight: 600, cursor: \"pointer\", fontFamily: \"inherit\", border: \"2px solid \" + (active ? B.coral : \"#ddd\"), background: active ? B.coral : \"#fff\", color: active ? \"#fff\" : \"#555\" });\n  const isComplaint = form.type === \"complaint\";\n\n  if (done) {\n    return (\n      <div>\n        <PageHero kicker=\"Customer care\" title=\"Thank you\" subtitle={isComplaint ? \"We are sorry something went wrong. Our team will look into it.\" : \"We appreciate you taking the time to tell us.\"} gradient=\"linear-gradient(135deg, #1F6F78, #2A9AA5)\" />\n        <section style={{ maxWidth: 640, margin: \"0 auto\", padding: \"50px 24px 70px\" }}>\n          <div style={{ ...card, textAlign: \"center\" }}>\n            <p style={{ fontSize: 13, color: \"#888\", marginBottom: 6 }}>Your reference</p>\n            <p style={{ fontSize: 28, fontWeight: 700, marginBottom: 14 }}>{done.reference}</p>\n            <p style={{ fontSize: 15, color: \"#555\", lineHeight: 1.7, marginBottom: 18 }}>Please quote this reference if you speak to us about it. We will contact you using the details you gave.</p>\n            {ready && <a className=\"btn bp\" href={whatsappUrl(CONTACT.whatsappNumber, \"Hello Peacock Paints, I sent a \" + form.type + \". Reference: \" + done.reference)} target=\"_blank\" rel=\"noopener noreferrer\" style={{ background: B.teal, justifyContent: \"center\", textDecoration: \"none\" }}>Follow up on WhatsApp</a>}\n          </div>\n        </section>\n      </div>\n    );\n  }\n\n  return (\n    <div>\n      <PageHero kicker=\"Customer care\" title=\"Complaints and feedback\" subtitle=\"Tell us what went well and what did not. Every message is read by our team and tracked until it is resolved.\" gradient=\"linear-gradient(135deg, #1F6F78, #2A9AA5)\" />\n      <section style={{ maxWidth: 720, margin: \"0 auto\", padding: \"40px 24px 70px\" }}>\n        <div style={card}>\n          <label style={label}>I want to send a</label>\n          <div style={{ display: \"flex\", gap: 8, marginBottom: 18, flexWrap: \"wrap\" }}>{TYPES.map(([v, l]) => <button type=\"button\" key={v} style={pill(form.type === v)} onClick={() => setForm(f => ({ ...f, type: v }))}>{l}</button>)}</div>\n          <div className=\"g2\" style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 14, marginBottom: 14 }}>\n            <div><label style={label}>Your name *</label><input className=\"si\" value={form.name} onChange={set(\"name\")} /></div>\n            <div><label style={label}>Phone</label><input className=\"si\" type=\"tel\" value={form.phone} onChange={set(\"phone\")} /></div>\n            <div><label style={label}>Email</label><input className=\"si\" type=\"email\" value={form.email} onChange={set(\"email\")} /></div>\n            <div><label style={label}>Product (if it is about one)</label><input className=\"si\" value={form.product} onChange={set(\"product\")} /></div>\n          </div>\n          <p style={{ fontSize: 12, color: \"#999\", margin: \"-6px 0 14px\" }}>Give a phone number or an email (or both) so we can reply.</p>\n          <div style={{ marginBottom: 14 }}><label style={label}>Where did you buy it? (shop or town, optional)</label><input className=\"si\" value={form.place} onChange={set(\"place\")} /></div>\n          <div style={{ marginBottom: 14 }}>\n            <label style={label}>How would you rate Peacock Paints? (optional)</label>\n            <div style={{ display: \"flex\", gap: 4 }}>\n              {[1, 2, 3, 4, 5].map(n => <button type=\"button\" key={n} aria-label={n + \" out of 5\"} aria-pressed={form.rating === n} onClick={() => setForm(f => ({ ...f, rating: f.rating === n ? 0 : n }))} style={{ fontSize: 26, lineHeight: 1, border: \"none\", background: \"none\", cursor: \"pointer\", color: n <= form.rating ? B.coral : \"#ccc\" }}>★</button>)}\n            </div>\n          </div>\n          <div style={{ marginBottom: 16 }}><label style={label}>Your message *</label><textarea className=\"si\" rows={5} value={form.message} onChange={set(\"message\")} style={{ resize: \"vertical\" }} placeholder={isComplaint ? \"What happened? Include the product, the colour and when you bought it if you can.\" : \"Tell us what you think.\"} /></div>\n          <div style={{ position: \"absolute\", left: \"-9999px\" }} aria-hidden=\"true\"><input tabIndex={-1} autoComplete=\"off\" value={form.website} onChange={set(\"website\")} /></div>\n          {errors.length > 0 && <div role=\"alert\" style={{ marginBottom: 14, padding: \"11px 14px\", borderRadius: 9, background: \"#fdecea\", color: \"#a12b1f\", fontSize: 14 }}>{errors.map(m => <div key={m}>{m}</div>)}</div>}\n          <button type=\"button\" className=\"btn bp\" onClick={submit} disabled={busy} style={{ width: \"100%\", justifyContent: \"center\" }}>{busy ? \"Sending...\" : \"Send\"}</button>\n          <p style={{ fontSize: 12, color: \"#999\", marginTop: 12, lineHeight: 1.6 }}>We use your details only to respond to your message.</p>\n        </div>\n      </section>\n    </div>\n  );\n}\n",
  "src/dashboard/ApplicationsAdmin.jsx": "import { useEffect, useState } from \"react\";\nimport { supabase } from \"../lib/supabase.js\";\nimport { toCsv, downloadCsv, when } from \"./csv.js\";\nimport { S, msgStyle } from \"./ui.js\";\n\nconst STATUSES = [[\"new\", \"New\"], [\"reviewing\", \"Reviewing\"], [\"approved\", \"Approved\"], [\"declined\", \"Declined\"]];\nconst TONE = { new: [\"#fff1e6\", \"#a4510f\"], reviewing: [\"#eef3fb\", \"#1f4f94\"], approved: [\"#e9f6ee\", \"#1d6b3a\"], declined: [\"#f2f2f2\", \"#666\"] };\nconst REG = { registered: \"Registered business\", in_progress: \"Registration in progress\", not_registered: \"Not registered yet\" };\nconst TAX = { has_tin: \"Has a TIN\", applying: \"Applying for a TIN\", none: \"No TIN yet\" };\n\nfunction Photos({ paths }) {\n  const [urls, setUrls] = useState(null);\n  const key = paths ? paths.join(\"|\") : \"\";\n  useEffect(() => {\n    let off = false;\n    if (!key) return undefined;\n    supabase.storage.from(\"applications\").createSignedUrls(key.split(\"|\"), 3600).then(({ data }) => { if (!off) setUrls((data || []).map(d => d.signedUrl).filter(Boolean)); });\n    return () => { off = true; };\n  }, [key]);\n  if (!paths || !paths.length) return <p style={{ fontSize: 13, color: \"#888\" }}>No photos.</p>;\n  if (!urls) return <p style={{ fontSize: 13, color: \"#888\" }}>Loading photos...</p>;\n  if (!urls.length) return <p style={{ fontSize: 13, color: \"#a12b1f\" }}>The photos could not be loaded.</p>;\n  return (\n    <div style={{ display: \"flex\", gap: 10, flexWrap: \"wrap\" }}>\n      {urls.map((u, i) => <a key={u} href={u} target=\"_blank\" rel=\"noopener noreferrer\" title=\"Open full size\"><img src={u} alt={\"Shop photo \" + (i + 1)} style={{ width: 150, height: 110, objectFit: \"cover\", borderRadius: 8, border: \"1px solid #ddd\" }} /></a>)}\n    </div>\n  );\n}\n\nexport default function ApplicationsAdmin({ isAdmin, onChange }) {\n  const [rows, setRows] = useState(null);\n  const [tick, setTick] = useState(0);\n  const [msg, setMsg] = useState(null);\n  const [status, setStatus] = useState(\"all\");\n  const [open, setOpen] = useState(null);\n  const [notes, setNotes] = useState({});\n\n  useEffect(() => {\n    let off = false;\n    supabase.from(\"dealer_applications\").select(\"*\").order(\"created_at\", { ascending: false }).limit(500)\n      .then(({ data, error }) => { if (off) return; if (error) setMsg({ ok: false, text: \"Could not load applications: \" + error.message + \" (has 03-peacock-forms.sql been run?)\" }); else setRows(data); });\n    return () => { off = true; };\n  }, [tick]);\n  const refresh = () => { setTick(t => t + 1); if (onChange) onChange(); };\n\n  async function changeStatus(r, next) {\n    const { error } = await supabase.from(\"dealer_applications\").update({ status: next }).eq(\"id\", r.id);\n    if (error) setMsg({ ok: false, text: \"Could not update: \" + error.message }); else refresh();\n  }\n  async function saveNotes(r) {\n    const { error } = await supabase.from(\"dealer_applications\").update({ staff_notes: (notes[r.id] != null ? notes[r.id] : r.staff_notes || \"\").trim() || null }).eq(\"id\", r.id);\n    if (error) setMsg({ ok: false, text: \"Could not save notes: \" + error.message }); else { setMsg({ ok: true, text: \"Notes saved.\" }); refresh(); }\n  }\n  async function remove(r) {\n    if (!window.confirm(\"Delete the application from \" + r.business_name + \" and its photos for good?\")) return;\n    if (r.photos && r.photos.length) await supabase.storage.from(\"applications\").remove(r.photos);\n    const { error } = await supabase.from(\"dealer_applications\").delete().eq(\"id\", r.id);\n    if (error) setMsg({ ok: false, text: \"Could not delete: \" + error.message }); else { setMsg({ ok: true, text: \"Deleted.\" }); refresh(); }\n  }\n\n  const shown = (rows || []).filter(r => status === \"all\" || r.status === status);\n  const exportCsv = () => downloadCsv(\"peacock-applications.csv\", toCsv(shown, [\n    [\"reference\", \"Reference\"], [r => when(r.created_at), \"Received\"], [\"kind\", \"Type\"], [\"status\", \"Status\"], [\"business_name\", \"Business\"], [\"contact_person\", \"Contact person\"], [\"phone\", \"Phone\"], [\"email\", \"Email\"],\n    [\"shop_town\", \"Town\"], [\"shop_address\", \"Address\"], [\"years_in_business\", \"Years in business\"], [r => REG[r.registration_status], \"Registration\"], [\"registration_number\", \"Registration no.\"],\n    [r => TAX[r.tax_status], \"Tax\"], [\"tin_number\", \"TIN\"], [\"kin_name\", \"Next of kin\"], [\"kin_phone\", \"Next of kin phone\"], [\"kin_relationship\", \"Relationship\"], [\"staff_notes\", \"Staff notes\"],\n  ]));\n  const chip = on => ({ padding: \"7px 16px\", borderRadius: 30, border: \"1px solid \" + (on ? \"#222\" : \"#ccc\"), background: on ? \"#222\" : \"#fff\", color: on ? \"#fff\" : \"#333\", fontSize: 13, fontWeight: 600, cursor: \"pointer\", fontFamily: \"inherit\" });\n  const line = (k, v) => v ? <div style={{ fontSize: 14, color: \"#444\", lineHeight: 1.8 }}><strong>{k}:</strong> {v}</div> : null;\n\n  return (\n    <div>\n      <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", marginBottom: 12, gap: 12, flexWrap: \"wrap\" }}>\n        <h2 style={{ fontSize: 22 }}>Distributor and dealer applications</h2>\n        <button style={S.btnGhost} disabled={!shown.length} onClick={exportCsv}>Download as spreadsheet (CSV)</button>\n      </div>\n      <p style={{ fontSize: 13, color: \"#777\", marginBottom: 16, lineHeight: 1.6 }}>Applications from the Distributor page, with the four shop photos. Only these details are collected now; terms are agreed when a contract is signed. Photos open in a private link that expires after an hour. Changing the status marks the alert as handled.</p>\n      {msg && <div role=\"alert\" style={msgStyle(msg.ok)}>{msg.text}</div>}\n      <div style={{ display: \"flex\", gap: 8, flexWrap: \"wrap\", marginBottom: 18 }}>\n        <button style={chip(status === \"all\")} onClick={() => setStatus(\"all\")}>Any status</button>\n        {STATUSES.map(([v, l]) => <button key={v} style={chip(status === v)} onClick={() => setStatus(v)}>{l} ({(rows || []).filter(r => r.status === v).length})</button>)}\n      </div>\n      {rows === null && !msg && <p style={{ color: \"#777\" }}>Loading...</p>}\n      {rows && shown.length === 0 && <div style={S.card}><p style={{ fontSize: 15, color: \"#555\" }}>Nothing here.</p></div>}\n      {shown.map(r => {\n        const [bg, fg] = TONE[r.status] || TONE.new;\n        const isOpen = open === r.id;\n        return (\n          <div key={r.id} style={{ ...S.card, marginBottom: 12 }}>\n            <div style={{ display: \"flex\", justifyContent: \"space-between\", gap: 12, flexWrap: \"wrap\" }}>\n              <div>\n                <strong style={{ fontSize: 16 }}>{r.business_name}</strong> <span style={{ fontSize: 12, padding: \"3px 10px\", borderRadius: 20, background: bg, color: fg, fontWeight: 700 }}>{STATUSES.find(s => s[0] === r.status)[1]}</span>\n                <div style={{ fontSize: 13, color: \"#777\", marginTop: 4 }}>{r.reference} · {r.kind} · {r.shop_town} · {when(r.created_at)}</div>\n                <div style={{ fontSize: 13, color: \"#555\", marginTop: 4 }}>{r.contact_person} · {r.phone}{r.email ? \" · \" + r.email : \"\"}</div>\n              </div>\n              <div style={{ display: \"flex\", gap: 8, alignItems: \"flex-start\" }}>\n                <select aria-label=\"Status\" style={{ ...S.input, width: \"auto\", padding: \"7px 10px\", fontSize: 13 }} value={r.status} onChange={e => changeStatus(r, e.target.value)}>{STATUSES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}</select>\n                <button style={S.small} onClick={() => setOpen(isOpen ? null : r.id)}>{isOpen ? \"Hide\" : \"Details\"}</button>\n              </div>\n            </div>\n            {isOpen && (\n              <div style={{ marginTop: 14, paddingTop: 14, borderTop: \"1px solid #eee\" }}>\n                {line(\"Address\", r.shop_address)}\n                {line(\"Years in business\", String(r.years_in_business))}\n                {line(\"Registration\", REG[r.registration_status] + (r.registration_number ? \" (\" + r.registration_number + \")\" : \"\"))}\n                {line(\"Tax\", TAX[r.tax_status] + (r.tin_number ? \" (\" + r.tin_number + \")\" : \"\"))}\n                {line(\"Next of kin\", r.kin_name + \", \" + r.kin_relationship + \", \" + r.kin_phone)}\n                <div style={{ margin: \"12px 0\" }}><Photos paths={r.photos} /></div>\n                <label style={S.label}>Staff notes (private)</label>\n                <textarea style={{ ...S.input, minHeight: 70 }} defaultValue={r.staff_notes || \"\"} onChange={e => setNotes(n => ({ ...n, [r.id]: e.target.value }))} />\n                <div style={{ display: \"flex\", gap: 10, marginTop: 10 }}>\n                  <button style={S.btn} onClick={() => saveNotes(r)}>Save notes</button>\n                  {isAdmin && <button style={S.btnGhost} onClick={() => remove(r)}>Delete</button>}\n                </div>\n              </div>\n            )}\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n",
  "src/dashboard/FeedbackAdmin.jsx": "import { useEffect, useState } from \"react\";\nimport { supabase } from \"../lib/supabase.js\";\nimport { toCsv, downloadCsv, when } from \"./csv.js\";\nimport { S, msgStyle } from \"./ui.js\";\n\nconst STATUSES = [[\"new\", \"New\"], [\"investigating\", \"Investigating\"], [\"resolved\", \"Resolved\"], [\"closed\", \"Closed\"]];\nconst TONE = { new: [\"#fff1e6\", \"#a4510f\"], investigating: [\"#eef3fb\", \"#1f4f94\"], resolved: [\"#e9f6ee\", \"#1d6b3a\"], closed: [\"#f2f2f2\", \"#666\"] };\nconst TYPES = [[\"all\", \"All\"], [\"complaint\", \"Complaints\"], [\"feedback\", \"Feedback\"], [\"compliment\", \"Compliments\"]];\n\nexport default function FeedbackAdmin({ isAdmin, onChange }) {\n  const [rows, setRows] = useState(null);\n  const [tick, setTick] = useState(0);\n  const [msg, setMsg] = useState(null);\n  const [type, setType] = useState(\"all\");\n  const [status, setStatus] = useState(\"all\");\n  const [open, setOpen] = useState(null);\n  const [notes, setNotes] = useState({});\n\n  useEffect(() => {\n    let off = false;\n    supabase.from(\"feedback\").select(\"*\").order(\"created_at\", { ascending: false }).limit(1000)\n      .then(({ data, error }) => { if (off) return; if (error) setMsg({ ok: false, text: \"Could not load feedback: \" + error.message + \" (has 03-peacock-forms.sql been run?)\" }); else setRows(data); });\n    return () => { off = true; };\n  }, [tick]);\n  const refresh = () => { setTick(t => t + 1); if (onChange) onChange(); };\n\n  async function changeStatus(r, next) {\n    const patch = { status: next, resolved_at: next === \"resolved\" || next === \"closed\" ? (r.resolved_at || new Date().toISOString()) : null };\n    const { error } = await supabase.from(\"feedback\").update(patch).eq(\"id\", r.id);\n    if (error) setMsg({ ok: false, text: \"Could not update: \" + error.message }); else refresh();\n  }\n  async function saveResolution(r) {\n    const { error } = await supabase.from(\"feedback\").update({ resolution: (notes[r.id] != null ? notes[r.id] : r.resolution || \"\").trim() || null }).eq(\"id\", r.id);\n    if (error) setMsg({ ok: false, text: \"Could not save: \" + error.message }); else { setMsg({ ok: true, text: \"Saved.\" }); refresh(); }\n  }\n  async function remove(r) {\n    if (!window.confirm(\"Delete this message from \" + r.name + \" for good?\")) return;\n    const { error } = await supabase.from(\"feedback\").delete().eq(\"id\", r.id);\n    if (error) setMsg({ ok: false, text: \"Could not delete: \" + error.message }); else { setMsg({ ok: true, text: \"Deleted.\" }); refresh(); }\n  }\n\n  const shown = (rows || []).filter(r => (type === \"all\" || r.type === type) && (status === \"all\" || r.status === status));\n  const exportCsv = () => downloadCsv(\"peacock-feedback.csv\", toCsv(shown, [\n    [\"reference\", \"Reference\"], [r => when(r.created_at), \"Received\"], [\"type\", \"Type\"], [\"status\", \"Status\"], [\"name\", \"Name\"], [\"phone\", \"Phone\"], [\"email\", \"Email\"],\n    [\"product\", \"Product\"], [\"place\", \"Bought at\"], [\"rating\", \"Rating\"], [\"message\", \"Message\"], [\"resolution\", \"What we did\"], [r => when(r.resolved_at), \"Resolved\"],\n  ]));\n  const chip = on => ({ padding: \"7px 16px\", borderRadius: 30, border: \"1px solid \" + (on ? \"#222\" : \"#ccc\"), background: on ? \"#222\" : \"#fff\", color: on ? \"#fff\" : \"#333\", fontSize: 13, fontWeight: 600, cursor: \"pointer\", fontFamily: \"inherit\" });\n\n  return (\n    <div>\n      <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", marginBottom: 12, gap: 12, flexWrap: \"wrap\" }}>\n        <h2 style={{ fontSize: 22 }}>Complaints and feedback</h2>\n        <button style={S.btnGhost} disabled={!shown.length} onClick={exportCsv}>Download as spreadsheet (CSV)</button>\n      </div>\n      <p style={{ fontSize: 13, color: \"#777\", marginBottom: 16, lineHeight: 1.6 }}>Messages from the Complaints and feedback page. Contact the customer yourself, write what was done under \"What we did\", then set the status to Resolved. Changing the status from New marks the alert as handled.</p>\n      {msg && <div role=\"alert\" style={msgStyle(msg.ok)}>{msg.text}</div>}\n      <div style={{ display: \"flex\", gap: 8, flexWrap: \"wrap\", marginBottom: 10 }}>{TYPES.map(([v, l]) => <button key={v} style={chip(type === v)} onClick={() => setType(v)}>{l}</button>)}</div>\n      <div style={{ display: \"flex\", gap: 8, flexWrap: \"wrap\", marginBottom: 18 }}>\n        <button style={chip(status === \"all\")} onClick={() => setStatus(\"all\")}>Any status</button>\n        {STATUSES.map(([v, l]) => <button key={v} style={chip(status === v)} onClick={() => setStatus(v)}>{l} ({(rows || []).filter(r => r.status === v).length})</button>)}\n      </div>\n      {rows === null && !msg && <p style={{ color: \"#777\" }}>Loading...</p>}\n      {rows && shown.length === 0 && <div style={S.card}><p style={{ fontSize: 15, color: \"#555\" }}>Nothing here.</p></div>}\n      {shown.map(r => {\n        const [bg, fg] = TONE[r.status] || TONE.new;\n        const isOpen = open === r.id;\n        return (\n          <div key={r.id} style={{ ...S.card, marginBottom: 12, borderColor: r.type === \"complaint\" && r.status === \"new\" ? \"#e8a39b\" : \"#e8e8e8\" }}>\n            <div style={{ display: \"flex\", justifyContent: \"space-between\", gap: 12, flexWrap: \"wrap\" }}>\n              <div style={{ flex: 1, minWidth: 240 }}>\n                <strong style={{ fontSize: 16, textTransform: \"capitalize\" }}>{r.type}</strong> <span style={{ fontSize: 12, padding: \"3px 10px\", borderRadius: 20, background: bg, color: fg, fontWeight: 700 }}>{STATUSES.find(s => s[0] === r.status)[1]}</span>\n                {r.rating ? <span style={{ marginLeft: 8, color: \"#c9772b\" }}>{\"★\".repeat(r.rating)}</span> : null}\n                <div style={{ fontSize: 13, color: \"#777\", marginTop: 4 }}>{r.reference} · {when(r.created_at)}</div>\n                <div style={{ fontSize: 13, color: \"#555\", marginTop: 4 }}>{r.name}{r.phone ? \" · \" + r.phone : \"\"}{r.email ? \" · \" + r.email : \"\"}</div>\n                <p style={{ fontSize: 14, color: \"#333\", margin: \"8px 0 0\", lineHeight: 1.6, whiteSpace: \"pre-wrap\" }}>{isOpen ? r.message : r.message.length > 160 ? r.message.slice(0, 160) + \"...\" : r.message}</p>\n              </div>\n              <div style={{ display: \"flex\", gap: 8, alignItems: \"flex-start\" }}>\n                <select aria-label=\"Status\" style={{ ...S.input, width: \"auto\", padding: \"7px 10px\", fontSize: 13 }} value={r.status} onChange={e => changeStatus(r, e.target.value)}>{STATUSES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}</select>\n                <button style={S.small} onClick={() => setOpen(isOpen ? null : r.id)}>{isOpen ? \"Hide\" : \"Details\"}</button>\n              </div>\n            </div>\n            {isOpen && (\n              <div style={{ marginTop: 14, paddingTop: 14, borderTop: \"1px solid #eee\" }}>\n                {(r.product || r.place) && <div style={{ fontSize: 14, color: \"#444\", marginBottom: 8 }}>{r.product ? \"Product: \" + r.product : \"\"}{r.product && r.place ? \" · \" : \"\"}{r.place ? \"Bought at: \" + r.place : \"\"}</div>}\n                <label style={S.label}>What we did (private)</label>\n                <textarea style={{ ...S.input, minHeight: 70 }} defaultValue={r.resolution || \"\"} onChange={e => setNotes(n => ({ ...n, [r.id]: e.target.value }))} />\n                <div style={{ display: \"flex\", gap: 10, marginTop: 10 }}>\n                  <button style={S.btn} onClick={() => saveResolution(r)}>Save</button>\n                  {isAdmin && <button style={S.btnGhost} onClick={() => remove(r)}>Delete</button>}\n                </div>\n              </div>\n            )}\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n",
  "src/dashboard/DashboardPage.jsx": "import { useCallback, useEffect, useState } from \"react\";\nimport { supabase } from \"../lib/supabase.js\";\nimport Login from \"./Login.jsx\";\nimport ProjectsAdmin from \"./ProjectsAdmin.jsx\";\nimport NewsAdmin from \"./NewsAdmin.jsx\";\nimport QuotesAdmin from \"./QuotesAdmin.jsx\";\nimport EnquiriesAdmin from \"./EnquiriesAdmin.jsx\";\nimport SubscribersAdmin from \"./SubscribersAdmin.jsx\";\nimport AlertsAdmin from \"./AlertsAdmin.jsx\";\nimport ApplicationsAdmin from \"./ApplicationsAdmin.jsx\";\nimport FeedbackAdmin from \"./FeedbackAdmin.jsx\";\nimport { S } from \"./ui.js\";\n\nconst COMING = [\"Media library\"];\n\nexport default function DashboardPage() {\n  const [session, setSession] = useState(undefined);\n  const [staff, setStaff] = useState({ uid: null, role: undefined });\n  const [tab, setTab] = useState(\"projects\");\n  const [fresh, setFresh] = useState({ quotes: 0, enquiries: 0, alerts: 0, applications: 0, feedback: 0 });\n  const uid = session ? session.user.id : null;\n\n  useEffect(() => {\n    if (!supabase) return undefined;\n    supabase.auth.getSession().then(({ data }) => setSession(data.session));\n    const { data } = supabase.auth.onAuthStateChange((_e, s) => setSession(s));\n    return () => data.subscription.unsubscribe();\n  }, []);\n\n  useEffect(() => {\n    if (!supabase || !uid) return undefined;\n    let off = false;\n    supabase.from(\"staff\").select(\"role\").eq(\"user_id\", uid).maybeSingle()\n      .then(({ data }) => { if (!off) setStaff({ uid, role: data ? data.role : false }); });\n    return () => { off = true; };\n  }, [uid]);\n\n  const role = staff.uid === uid ? staff.role : undefined;\n  const isStaff = !!role;\n  const countNew = useCallback(() => {\n    const count = table => supabase.from(table).select(\"id\", { count: \"exact\", head: true }).eq(\"status\", \"new\").then(({ count: c }) => c || 0);\n    const openAlerts = supabase.from(\"lead_alerts\").select(\"id\", { count: \"exact\", head: true }).eq(\"status\", \"open\").then(({ count: c }) => c || 0);\n    Promise.all([count(\"quote_requests\"), count(\"enquiries\"), openAlerts, count(\"dealer_applications\"), count(\"feedback\")]).then(([quotes, enquiries, alerts, applications, feedback]) => setFresh({ quotes, enquiries, alerts, applications, feedback }));\n  }, []);\n  useEffect(() => { if (supabase && isStaff) countNew(); }, [isStaff, tab, countNew]);\n\n  if (!supabase) return <p style={{ padding: 60, textAlign: \"center\" }}>The database is not connected yet (src/config/supabase.js is blank).</p>;\n  if (session === undefined) return <p style={{ padding: 60, textAlign: \"center\", color: \"#777\" }}>Loading...</p>;\n  if (!session) return <Login />;\n  if (role === undefined) return <p style={{ padding: 60, textAlign: \"center\", color: \"#777\" }}>Checking your access...</p>;\n  if (role === false) {\n    return (\n      <div style={{ maxWidth: 480, margin: \"0 auto\", padding: \"70px 24px\", textAlign: \"center\" }}>\n        <h1 style={{ fontSize: 24, marginBottom: 10 }}>No access</h1>\n        <p style={{ fontSize: 15, color: \"#555\", lineHeight: 1.7, marginBottom: 20 }}>You are signed in as {session.user.email}, but this account has not been added to the staff list. Ask an administrator to add you.</p>\n        <button style={S.btnGhost} onClick={() => supabase.auth.signOut()}>Sign out</button>\n      </div>\n    );\n  }\n\n  const badge = n => (n ? \" (\" + n + \" new)\" : \"\");\n  const TABS = [[\"projects\", \"Projects\"], [\"news\", \"News & updates\"], [\"quotes\", \"Quote requests\" + badge(fresh.quotes)], [\"enquiries\", \"Enquiries\" + badge(fresh.enquiries)], [\"applications\", \"Applications\" + badge(fresh.applications)], [\"feedback\", \"Feedback\" + badge(fresh.feedback)], [\"alerts\", \"Alerts\" + (fresh.alerts ? \" (\" + fresh.alerts + \" waiting)\" : \"\")], [\"subscribers\", \"Newsletter subscribers\"]];\n  return (\n    <div style={S.wrap}>\n      <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", flexWrap: \"wrap\", gap: 12, marginBottom: 26 }}>\n        <div>\n          <h1 style={{ fontSize: 28 }}>Website dashboard</h1>\n          <p style={{ fontSize: 13, color: \"#777\", marginTop: 4 }}>Signed in as {session.user.email} ({role})</p>\n        </div>\n        <div style={{ display: \"flex\", gap: 10 }}>\n          <a href=\"#/\" style={{ ...S.btnGhost, textDecoration: \"none\" }}>View website</a>\n          <button style={S.btnGhost} onClick={() => supabase.auth.signOut()}>Sign out</button>\n        </div>\n      </div>\n      <div style={{ display: \"flex\", gap: 8, flexWrap: \"wrap\", marginBottom: 26 }}>\n        {TABS.map(([id, label]) => (\n          <button key={id} onClick={() => setTab(id)} aria-pressed={tab === id} style={{ padding: \"8px 18px\", borderRadius: 30, border: \"1px solid \" + (tab === id ? \"#222\" : \"#ccc\"), background: tab === id ? \"#222\" : \"#fff\", color: tab === id ? \"#fff\" : \"#333\", fontSize: 13, fontWeight: 700, cursor: \"pointer\", fontFamily: \"inherit\" }}>{label}</button>\n        ))}\n        {COMING.map(c => <span key={c} title=\"Coming in a later step\" style={{ padding: \"8px 18px\", borderRadius: 30, border: \"1px dashed #ccc\", color: \"#aaa\", fontSize: 13 }}>{c}</span>)}\n      </div>\n      {tab === \"projects\" && <ProjectsAdmin />}\n      {tab === \"news\" && <NewsAdmin />}\n      {tab === \"quotes\" && <QuotesAdmin onChange={countNew} />}\n      {tab === \"enquiries\" && <EnquiriesAdmin onChange={countNew} />}\n      {tab === \"applications\" && <ApplicationsAdmin isAdmin={role === \"admin\"} onChange={countNew} />}\n      {tab === \"feedback\" && <FeedbackAdmin isAdmin={role === \"admin\"} onChange={countNew} />}\n      {tab === \"alerts\" && <AlertsAdmin isAdmin={role === \"admin\"} onChange={countNew} />}\n      {tab === \"subscribers\" && <SubscribersAdmin />}\n    </div>\n  );\n}\n",
};
const DISTRIBUTOR = "import { useState } from \"react\";\nimport { CONTACT } from \"../config/contact.js\";\nimport { B } from \"../data/theme.js\";\nimport { whatsappReady, whatsappUrl } from \"../utils/messaging.js\";\nimport { submitApplication } from \"../lib/forms.js\";\nimport PageHero from \"../components/common/PageHero.jsx\";\n\nconst STEPS = [\"Your business\", \"Shop location\", \"Shop photos\", \"Registration\", \"Next of kin\", \"Review\"];\nconst PHOTO_SLOTS = [\"Shop front (outside)\", \"Inside the shop\", \"Shelves or stock\", \"Street or surroundings\"];\nconst REG = [[\"registered\", \"Registered business\"], [\"in_progress\", \"Registration in progress\"], [\"not_registered\", \"Not registered yet\"]];\nconst TAX = [[\"has_tin\", \"I have a TIN (tax number)\"], [\"applying\", \"Applying for a TIN\"], [\"none\", \"No TIN yet\"]];\nconst EMPTY = { kind: \"Distributor\", business: \"\", person: \"\", phone: \"\", email: \"\", town: \"\", address: \"\", years: \"\", regStatus: \"\", regNumber: \"\", taxStatus: \"\", tin: \"\", kinName: \"\", kinPhone: \"\", kinRelation: \"\", consent: false, website: \"\" };\nconst label = { fontSize: 12, fontWeight: 600, color: \"#555\", display: \"block\", marginBottom: 6 };\n\nexport default function DistributorPage() {\n  const [form, setForm] = useState(EMPTY);\n  const [step, setStep] = useState(0);\n  const [photos, setPhotos] = useState([null, null, null, null]);\n  const [previews, setPreviews] = useState([null, null, null, null]);\n  const [errors, setErrors] = useState([]);\n  const [busy, setBusy] = useState(false);\n  const [done, setDone] = useState(null);\n  const set = key => e => setForm(f => ({ ...f, [key]: e.target.value }));\n  const ready = whatsappReady(CONTACT.whatsappNumber);\n\n  const pick = (i, file) => {\n    if (!file) return;\n    if (!/^image\\/(jpeg|png|webp)$/.test(file.type)) { setErrors([\"Please use a JPG, PNG or WebP photo.\"]); return; }\n    if (file.size > 25 * 1024 * 1024) { setErrors([\"That photo is very large. Please choose one under 25 MB.\"]); return; }\n    setErrors([]);\n    if (previews[i]) URL.revokeObjectURL(previews[i]);\n    setPhotos(p => p.map((x, k) => (k === i ? file : x)));\n    setPreviews(p => p.map((x, k) => (k === i ? URL.createObjectURL(file) : x)));\n  };\n\n  const check = s => {\n    const e = [];\n    const need = (v, msg) => { if (!String(v).trim()) e.push(msg); };\n    if (s === 0) { need(form.business, \"Enter your business name.\"); need(form.person, \"Enter the contact person's name.\"); if (form.phone.replace(/\\D/g, \"\").length < 7) e.push(\"Enter a phone number.\"); }\n    if (s === 1) need(form.town, \"Enter the town or district of your shop.\");\n    if (s === 2 && photos.some(p => !p)) e.push(\"Please add all 4 photos.\");\n    if (s === 3) {\n      if (form.years === \"\" || Number(form.years) < 0 || Number(form.years) > 100) e.push(\"Enter how many years you have been in business (0 if new).\");\n      if (!form.regStatus) e.push(\"Choose your registration status.\");\n      if (!form.taxStatus) e.push(\"Choose your tax (TIN) status.\");\n    }\n    if (s === 4) { need(form.kinName, \"Enter your next of kin's name.\"); if (form.kinPhone.replace(/\\D/g, \"\").length < 7) e.push(\"Enter your next of kin's phone number.\"); need(form.kinRelation, \"Enter how they are related to you.\"); }\n    if (s === 5 && !form.consent) e.push(\"Please tick the box to confirm.\");\n    return e;\n  };\n  const next = () => { const e = check(step); setErrors(e); if (!e.length) setStep(step + 1); };\n  const back = () => { setErrors([]); setStep(step - 1); };\n  async function submit() {\n    const e = check(5);\n    for (let s = 0; s < 5 && !e.length; s++) { const x = check(s); if (x.length) { setStep(s); setErrors(x); return; } }\n    setErrors(e);\n    if (e.length || busy) return;\n    if (form.website) { setDone({ reference: \"PP-DIST-0000\" }); return; }\n    setBusy(true);\n    const r = await submitApplication(form, photos);\n    setBusy(false);\n    if (r.ok) setDone({ reference: r.reference }); else setErrors([r.error]);\n  }\n\n  const card = { background: \"#fff\", border: \"1px solid #eee\", borderRadius: 14, padding: 28 };\n  const pill = active => ({ padding: \"8px 20px\", borderRadius: 22, fontSize: 14, fontWeight: 600, cursor: \"pointer\", fontFamily: \"inherit\", border: \"2px solid \" + (active ? B.coral : \"#ddd\"), background: active ? B.coral : \"#fff\", color: active ? \"#fff\" : \"#555\" });\n  const field = (key, text, props = {}) => <div style={{ marginBottom: 14 }}><label style={label}>{text}</label><input className=\"si\" value={form[key]} onChange={set(key)} {...props} /></div>;\n  const choose = (key, options, text) => (\n    <div style={{ marginBottom: 14 }}>\n      <label style={label}>{text}</label>\n      <div style={{ display: \"flex\", gap: 8, flexWrap: \"wrap\" }}>{options.map(([v, l]) => <button type=\"button\" key={v} style={pill(form[key] === v)} onClick={() => setForm(f => ({ ...f, [key]: v }))}>{l}</button>)}</div>\n    </div>\n  );\n  const lab = (opts, v) => (opts.find(o => o[0] === v) || [0, \"-\"])[1];\n\n  if (done) {\n    const text = \"Hello Peacock Paints, I have submitted a \" + form.kind.toLowerCase() + \" application. Reference: \" + done.reference + \". Business: \" + form.business.trim() + \".\";\n    return (\n      <div>\n        <PageHero kicker=\"Work with us\" title=\"Application received\" subtitle=\"Thank you. Our team will review it and get back to you.\" gradient=\"linear-gradient(135deg, #5C2D6D, #8B4AAD)\" />\n        <section style={{ maxWidth: 640, margin: \"0 auto\", padding: \"50px 24px 70px\" }}>\n          <div style={{ ...card, textAlign: \"center\" }}>\n            <p style={{ fontSize: 13, color: \"#888\", marginBottom: 6 }}>Your reference</p>\n            <p style={{ fontSize: 28, fontWeight: 700, marginBottom: 14 }}>{done.reference}</p>\n            <p style={{ fontSize: 15, color: \"#555\", lineHeight: 1.7, marginBottom: 18 }}>Please keep this reference. Sending this form does not make you a Peacock Paints dealer or distributor. Terms and conditions are agreed with you when a contract is signed.</p>\n            {ready && <a className=\"btn bp\" href={whatsappUrl(CONTACT.whatsappNumber, text)} target=\"_blank\" rel=\"noopener noreferrer\" style={{ background: B.teal, justifyContent: \"center\", textDecoration: \"none\" }}>Tell us on WhatsApp that you applied</a>}\n          </div>\n        </section>\n      </div>\n    );\n  }\n\n  return (\n    <div>\n      <PageHero kicker=\"Work with us\" title=\"Become a Peacock Paints distributor\" subtitle=\"We are looking for businesses across East Africa who want to grow with a trusted, locally manufactured paint brand.\" gradient=\"linear-gradient(135deg, #5C2D6D, #8B4AAD)\" />\n      <section style={{ maxWidth: 760, margin: \"0 auto\", padding: \"40px 24px 70px\" }}>\n        <div style={{ display: \"flex\", gap: 6, marginBottom: 22 }} aria-label={\"Step \" + (step + 1) + \" of \" + STEPS.length}>\n          {STEPS.map((s, i) => <div key={s} style={{ flex: 1 }}><div style={{ height: 5, borderRadius: 3, background: i <= step ? B.coral : \"#e5e5e5\" }} /><div style={{ fontSize: 11, color: i === step ? \"#222\" : \"#999\", fontWeight: i === step ? 700 : 500, marginTop: 6 }}>{i + 1}. {s}</div></div>)}\n        </div>\n        <div style={card}>\n          <h2 style={{ fontFamily: \"'Playfair Display', serif\", fontSize: 26, marginBottom: 18 }}>{STEPS[step]}</h2>\n\n          {step === 0 && (\n            <div>\n              <label style={label}>I am interested in becoming a</label>\n              <div style={{ display: \"flex\", gap: 8, marginBottom: 18 }}>{[\"Distributor\", \"Dealer\"].map(k => <button type=\"button\" key={k} style={pill(form.kind === k)} onClick={() => setForm(f => ({ ...f, kind: k }))}>{k}</button>)}</div>\n              {field(\"business\", \"Business name *\")}\n              {field(\"person\", \"Your full name *\")}\n              {field(\"phone\", \"Phone number *\", { type: \"tel\" })}\n              {field(\"email\", \"Email (optional)\", { type: \"email\" })}\n            </div>\n          )}\n          {step === 1 && (\n            <div>\n              {field(\"town\", \"Town or district of your shop *\")}\n              {field(\"address\", \"Street, building or landmark (optional)\")}\n            </div>\n          )}\n          {step === 2 && (\n            <div>\n              <p style={{ fontSize: 13.5, color: \"#666\", lineHeight: 1.6, marginBottom: 16 }}>Add 4 clear photos of your shop. Only our team can see them.</p>\n              <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(auto-fit,minmax(200px,1fr))\", gap: 14 }}>\n                {PHOTO_SLOTS.map((name, i) => (\n                  <div key={name}>\n                    <label style={label}>{i + 1}. {name} *</label>\n                    <label style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"center\", height: 130, border: \"2px dashed \" + (photos[i] ? B.teal : \"#ccc\"), borderRadius: 10, overflow: \"hidden\", cursor: \"pointer\", background: \"#fafafa\", color: \"#888\", fontSize: 13 }}>\n                      {previews[i] ? <img src={previews[i]} alt={name} style={{ width: \"100%\", height: \"100%\", objectFit: \"cover\" }} /> : \"Tap to add photo\"}\n                      <input type=\"file\" accept=\"image/jpeg,image/png,image/webp\" data-slot={i} style={{ display: \"none\" }} onChange={e => { pick(i, e.target.files && e.target.files[0]); e.target.value = \"\"; }} />\n                    </label>\n                  </div>\n                ))}\n              </div>\n            </div>\n          )}\n          {step === 3 && (\n            <div>\n              {field(\"years\", \"Years in business *\", { type: \"number\", min: 0, max: 100 })}\n              {choose(\"regStatus\", REG, \"Business registration *\")}\n              {form.regStatus === \"registered\" && field(\"regNumber\", \"Registration number (optional)\")}\n              {choose(\"taxStatus\", TAX, \"Tax status *\")}\n              {form.taxStatus === \"has_tin\" && field(\"tin\", \"TIN (optional)\")}\n            </div>\n          )}\n          {step === 4 && (\n            <div>\n              <p style={{ fontSize: 13.5, color: \"#666\", lineHeight: 1.6, marginBottom: 16 }}>Someone we can contact if we cannot reach you.</p>\n              {field(\"kinName\", \"Next of kin's full name *\")}\n              {field(\"kinPhone\", \"Next of kin's phone number *\", { type: \"tel\" })}\n              {field(\"kinRelation\", \"Relationship to you *\")}\n            </div>\n          )}\n          {step === 5 && (\n            <div>\n              <div style={{ fontSize: 14, color: \"#444\", lineHeight: 1.9, marginBottom: 16 }}>\n                <div><strong>{form.kind}:</strong> {form.business} ({form.person}, {form.phone}{form.email ? \", \" + form.email : \"\"})</div>\n                <div><strong>Shop:</strong> {form.town}{form.address ? \", \" + form.address : \"\"}</div>\n                <div><strong>Photos:</strong> {photos.filter(Boolean).length} of 4 added</div>\n                <div><strong>In business:</strong> {form.years} year(s) · {lab(REG, form.regStatus)} · {lab(TAX, form.taxStatus)}</div>\n                <div><strong>Next of kin:</strong> {form.kinName} ({form.kinRelation}, {form.kinPhone})</div>\n              </div>\n              <div style={{ position: \"absolute\", left: \"-9999px\" }} aria-hidden=\"true\"><input tabIndex={-1} autoComplete=\"off\" value={form.website} onChange={set(\"website\")} /></div>\n              <label style={{ display: \"flex\", gap: 10, alignItems: \"flex-start\", fontSize: 13.5, color: \"#444\", lineHeight: 1.6, cursor: \"pointer\" }}>\n                <input type=\"checkbox\" checked={form.consent} onChange={e => setForm(f => ({ ...f, consent: e.target.checked }))} style={{ marginTop: 4, accentColor: B.coral }} />\n                <span>I confirm these details are true. I understand that sending this form does not make me a Peacock Paints dealer or distributor, that terms are agreed when a contract is signed, and that Peacock Paints may use these details and photos to assess my application.</span>\n              </label>\n            </div>\n          )}\n\n          {errors.length > 0 && <div role=\"alert\" style={{ margin: \"16px 0 0\", padding: \"11px 14px\", borderRadius: 9, background: \"#fdecea\", color: \"#a12b1f\", fontSize: 14 }}>{errors.map(m => <div key={m}>{m}</div>)}</div>}\n          <div style={{ display: \"flex\", gap: 10, marginTop: 22 }}>\n            {step > 0 && <button type=\"button\" className=\"btn bd\" onClick={back} disabled={busy}>Back</button>}\n            {step < STEPS.length - 1\n              ? <button type=\"button\" className=\"btn bp\" onClick={next} style={{ marginLeft: \"auto\" }}>Next</button>\n              : <button type=\"button\" className=\"btn bp\" onClick={submit} disabled={busy} style={{ marginLeft: \"auto\" }}>{busy ? \"Sending...\" : \"Send application\"}</button>}\n          </div>\n        </div>\n      </section>\n    </div>\n  );\n}\n";

const problems = [], notes = [], contents = {};
const read = f => fs.readFileSync(f, "utf8").replace(/\r\n/g, "\n");
for (const f of ["src/lib/supabase.js", "src/dashboard/AlertsAdmin.jsx", "src/dashboard/uploads.js", "src/dashboard/csv.js", "src/dashboard/ui.js", "src/pages/PageSwitch.jsx", "src/pages/DistributorPage.jsx"]) if (!fs.existsSync(f)) problems.push("Missing " + f + " (run the earlier scripts first)");
if (fs.existsSync("src/pages/FeedbackPage.jsx")) problems.push("The forms are already installed");
if (fs.existsSync("src/dashboard/DashboardPage.jsx") && !read("src/dashboard/DashboardPage.jsx").includes("import AlertsAdmin")) problems.push("src/dashboard/DashboardPage.jsx is not the Alerts version (run add-dashboard-alerts.mjs first)");
if (fs.existsSync("src/pages/DistributorPage.jsx") && !read("src/pages/DistributorPage.jsx").includes("Express your interest")) problems.push("src/pages/DistributorPage.jsx is not the version I expected (it has been changed since)");

if (fs.existsSync("src/pages/PageSwitch.jsx")) {
  let t = read("src/pages/PageSwitch.jsx");
  const find = '      ) : pg === "projects" ? (';
  if (t.split(find).length - 1 !== 1) problems.push("src/pages/PageSwitch.jsx: expected 1 match for the projects line");
  else contents["src/pages/PageSwitch.jsx"] = 'import FeedbackPage from "./FeedbackPage.jsx";\n' + t.replace(find, () => '      ) : pg === "feedback" ? (\n        <FeedbackPage />\n' + find);
}
if (fs.existsSync("src/pages/ContactPage.jsx")) {
  const t = read("src/pages/ContactPage.jsx");
  const find = '          <div style={detail}><MailIcon /><a href={"mailto:" + CONTACT.salesEmail} style={{ color: "inherit" }}>{CONTACT.salesEmail}</a></div>';
  if (t.split(find).length - 1 === 1 && !t.includes("#/feedback")) contents["src/pages/ContactPage.jsx"] = t.replace(find, () => find + '\n          <div style={{ ...detail, marginTop: 6 }}><a href="#/feedback" style={{ color: "inherit", fontWeight: 600 }}>Complaint or feedback? Tell us here</a></div>');
  else notes.push("Could not add the feedback link to the Contact page. Add a link to #/feedback in the menu or footer yourself (send me navData.js and Footer.jsx and I will do it).");
}
try {
  const esbuild = createRequire(import.meta.url)("esbuild");
  const check = (n, c) => { try { esbuild.transformSync(c, { loader: "jsx" }); } catch (e) { problems.push("Syntax problem in " + n + ": " + String(e.message).split("\n")[0]); } };
  for (const [n, c] of Object.entries(NEW_FILES)) check(n, c);
  check("DistributorPage.jsx", DISTRIBUTOR);
  for (const [n, c] of Object.entries(contents)) check(n, c);
} catch { notes.push("esbuild not found, so no syntax check here; run npx eslint src afterwards"); }

if (problems.length) { console.log("\nNothing was changed. Problems:"); problems.forEach(p => console.log("  - " + p)); process.exit(1); }
for (const [f, c] of Object.entries(NEW_FILES)) { fs.mkdirSync(f.slice(0, f.lastIndexOf("/")), { recursive: true }); fs.writeFileSync(f, c); }
fs.writeFileSync("src/pages/DistributorPage.jsx", DISTRIBUTOR);
for (const [f, c] of Object.entries(contents)) fs.writeFileSync(f, c);
console.log("\nDone. The Distributor page is now a step-by-step form, #/feedback exists, and the dashboard has Applications and Feedback tabs.");
notes.forEach(n => console.log("Note: " + n));
console.log("\nNext:\n  1. npx eslint src\n  2. Run 03-peacock-forms.sql in the Supabase SQL Editor\n  3. npm run dev, send a test application and a test complaint, then check the dashboard\nUndo anytime with:  git checkout . ; git clean -fd src");
